function apiTenderRow(args) {
  const t = findTender_(String(args.name || '').trim(), String(args.no || '').trim());
  if (!t) return null;
  const o = {}; TENDER_FIELDS.forEach(k => { o[k] = t[k] == null ? '' : String(t[k]); });
  return o;
}
